class Solution:
    def maxAbsValExpr(self, arr1: List[int], arr2: List[int]) -> int:
        n = len(arr1)
        ans = 0
        for i in range(n):
            for j in range(i + 1, n):
                ans = max(ans, abs(arr1[i]-arr1[j]) + abs(arr2[i]-arr2[j]) + i - j)
        return ans

